#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maximumSetSize(std::vector<int>& nums1, std::vector<int>& nums2) {
        int n = nums1.size();
        std::unordered_set<int> s1(nums1.begin(), nums1.end());
        std::unordered_set<int> s2(nums2.begin(), nums2.end());
        int common = 0;
        for (int x : s1) {
            if (s2.count(x)) ++common;
        }
        int u1 = s1.size() - common;
        int u2 = s2.size() - common;
        int take1 = std::min(u1, n / 2);
        int take2 = std::min(u2, n / 2);
        int rem1 = n / 2 - take1;
        int rem2 = n / 2 - take2;
        int takeCommon = std::min(common, rem1 + rem2);
        return take1 + take2 + takeCommon;
    }
};

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int maximumSetSize(int[] nums1, int[] nums2) {
        int n = nums1.length;
        Set<Integer> s1 = new HashSet<>();
        for (int x : nums1) s1.add(x);
        Set<Integer> s2 = new HashSet<>();
        for (int x : nums2) s2.add(x);

        int common = 0;
        for (int x : s1) {
            if (s2.contains(x)) common++;
        }
        int u1 = s1.size() - common;
        int u2 = s2.size() - common;
        int take1 = Math.min(u1, n / 2);
        int take2 = Math.min(u2, n / 2);
        int rem1 = n / 2 - take1;
        int rem2 = n / 2 - take2;
        int takeCommon = Math.min(common, rem1 + rem2);
        return take1 + take2 + takeCommon;
    }
}

var maximumSetSize = function(nums1, nums2) {
    const n = nums1.length;
    const s1 = new Set(nums1);
    const s2 = new Set(nums2);
    let common = 0;
    for (const x of s1) {
        if (s2.has(x)) common++;
    }
    const u1 = s1.size - common;
    const u2 = s2.size - common;
    const take1 = Math.min(u1, Math.floor(n / 2));
    const take2 = Math.min(u2, Math.floor(n / 2));
    const rem1 = Math.floor(n / 2) - take1;
    const rem2 = Math.floor(n / 2) - take2;
    const takeCommon = Math.min(common, rem1 + rem2);
    return take1 + take2 + takeCommon;
};
